<?php
/** Template Name: فرصت‌های همکاری */
declare(strict_types=1);
if (!defined('ABSPATH')) exit;
get_header();
$postId = (int) get_the_ID();
$defaultDepartments = [
    'rd' => ['title' => 'تحقیق و توسعه', 'body' => 'فرصت همکاری در طراحی و بهبود محصولات و راهکارهای نورپردازی.', 'order' => 1],
    'projects' => ['title' => 'واحد پروژه‌ها', 'body' => 'همکاری در برنامه‌ریزی، هماهنگی و اجرای پروژه‌های نورپردازی شهری.', 'order' => 2],
    'finance' => ['title' => 'واحد مالی', 'body' => 'همکاری در امور مالی، حسابداری و پشتیبانی فرایندهای سازمان.', 'order' => 3],
    'it' => ['title' => 'فناوری اطلاعات', 'body' => 'همکاری در نگهداری و توسعه زیرساخت‌ها و سامانه‌های فناوری.', 'order' => 4],
];
$sections = es_get_sections($postId);
$byType = [];
foreach ($sections as $section) if (isset($section['type'])) $byType[$section['type']] = $section;
$hero = $byType['recruitment-hero'] ?? ['enabled' => true, 'fields' => ['title' => 'به خانواده عرفان صنعت بپیوندید', 'body' => 'ما از همکاری با افراد متخصص، مسئولیت‌پذیر و مشتاق یادگیری استقبال می‌کنیم.']];
$departments = [];
foreach ($defaultDepartments as $key => $fields) {
    $type = 'recruitment-dept-' . $key;
    $dept = $byType[$type] ?? ['type' => $type, 'enabled' => true, 'order' => $fields['order'], 'fields' => []];
    $dept['fields'] = array_merge($fields, is_array($dept['fields'] ?? null) ? $dept['fields'] : []);
    $departments[$key] = $dept;
}
?>
<main id="primary" class="site-main mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-8">
<?php if (!empty($hero['enabled'])) : $heroFields = is_array($hero['fields'] ?? null) ? $hero['fields'] : []; ?><header class="mb-8 rounded-3xl bg-slate-900 p-7 text-white md:p-11"><p class="text-xs font-bold text-emerald-300">فرصت‌های شغلی</p><h1 class="mt-3 text-3xl font-black leading-relaxed md:text-5xl"><?php echo esc_html((string) ($heroFields['title'] ?? 'به خانواده عرفان صنعت بپیوندید')); ?></h1><p class="mt-4 max-w-3xl text-sm leading-8 text-slate-200"><?php echo esc_html((string) ($heroFields['body'] ?? '')); ?></p></header><?php endif; ?>
<section data-recruit-tabs="true" class="rounded-3xl bg-white p-5 md:p-8"><div role="tablist" aria-label="واحدهای سازمانی" class="mb-6 flex flex-wrap gap-2"><?php $first = true; foreach ($departments as $key => $dept) : if (empty($dept['enabled'])) continue; $field = $dept['fields']; ?><button type="button" role="tab" aria-selected="<?php echo $first ? 'true' : 'false'; ?>" data-recruit-tab-btn="<?php echo esc_attr($key); ?>" class="rounded-xl <?php echo $first ? 'bg-emerald-700 text-white shadow-sm' : 'border border-slate-200 bg-slate-50 text-slate-700'; ?> px-4 py-3 text-sm font-bold"><?php echo esc_html((string) $field['title']); ?></button><?php $first = false; endforeach; ?></div>
<?php $first = true; foreach ($departments as $key => $dept) : if (empty($dept['enabled'])) continue; $field = $dept['fields']; ?><div role="tabpanel" data-recruit-panel="<?php echo esc_attr($key); ?>" class="<?php echo $first ? '' : 'hidden'; ?> rounded-2xl bg-slate-50 p-5"<?php echo $first ? '' : ' hidden'; ?>><h2 class="text-lg font-black text-slate-900"><?php echo esc_html((string) $field['title']); ?></h2><p class="mt-3 text-sm leading-7 text-slate-600"><?php echo esc_html((string) $field['body']); ?></p><?php if (is_array($field['roles'] ?? null) && $field['roles'] !== []) : ?><ul class="mt-4 list-inside list-disc space-y-2 text-sm text-slate-700"><?php foreach ($field['roles'] as $role) if (is_scalar($role) && trim((string) $role) !== '') : ?><li><?php echo esc_html((string) $role); ?></li><?php endif; ?></ul><?php endif; ?></div><?php $first = false; endforeach; ?></section>
<section data-recruit-form-slot="true" class="mt-7 rounded-3xl border border-emerald-100 bg-emerald-50 p-6 md:p-9"><div class="mb-6"><h2 class="text-xl font-black text-slate-900">ارسال رزومه و درخواست همکاری</h2><p class="mt-3 max-w-2xl text-sm leading-7 text-slate-600">فرم زیر را تکمیل کنید تا درخواست شما برای واحد منابع انسانی ارسال شود. فایل رزومه باید PDF یا Word و حداکثر ۵ مگابایت باشد.</p></div><form data-recruitment-form="true" method="post" enctype="multipart/form-data" class="grid gap-4 md:grid-cols-2"><label class="block text-sm font-bold text-slate-700">نام و نام خانوادگی<input name="name" type="text" autocomplete="name" required minlength="2" class="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm" placeholder="نام شما"></label><label class="block text-sm font-bold text-slate-700">شماره تماس<input name="phone" type="tel" autocomplete="tel" required inputmode="tel" class="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm" placeholder="۰۹۱۲۱۲۳۴۵۶۷"></label><label class="block text-sm font-bold text-slate-700">ایمیل (اختیاری)<input name="email" type="email" autocomplete="email" class="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm" placeholder="name@example.com"></label><label class="block text-sm font-bold text-slate-700">واحد موردنظر<select name="department" required class="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm"><?php foreach ($departments as $key => $dept) : if (!empty($dept['enabled'])) : ?><option value="<?php echo esc_attr($key); ?>"><?php echo esc_html((string) $dept['fields']['title']); ?></option><?php endif; endforeach; ?></select></label><label class="block text-sm font-bold text-slate-700 es-form-full-row">شرح درخواست<textarea name="message" rows="5" required class="mt-2 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm" placeholder="درباره تجربه و زمینه همکاری خود بنویسید"></textarea></label><label class="block text-sm font-bold text-slate-700 es-form-full-row">رزومه<input name="resume" type="file" accept=".pdf,.doc,.docx" required class="mt-2 block w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm "><span class="mt-2 block text-xs font-normal text-slate-500">PDF، DOC یا DOCX — حداکثر ۵ مگابایت</span></label><label class="hidden" aria-hidden="true">وب‌سایت<input type="text" name="website" tabindex="-1" autocomplete="off" value=""></label><p data-recruitment-status="true" class="text-sm text-slate-600 es-form-full-row" role="status" aria-live="polite"></p><div class="es-form-full-row"><button type="submit" class="inline-flex rounded-xl bg-emerald-700 px-5 py-3 text-sm font-extrabold text-white ">ارسال درخواست همکاری</button></div></form></section>
</main>
<?php get_footer(); ?>
